  app.post('/v1/customer-imports', async (request, reply) => {
    const principal = await authenticate(request, 'customers:write');
    const input = importSchema.parse(request.body);
    const importId = await service.importCustomerArtifact(principal.merchantId, input.source, JSON.stringify(input.record));
    return reply.code(201).send({ id: importId });
  });
  app.post('/v1/customers/:id/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const key = request.headers['idempotency-key'];
    if (typeof key !== 'string' || !isValidIdempotencyKey(key)) {
      return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    }
    const result = await erasure.requestErasure(principal.merchantId, id, key);
    return reply.code(202).send(result);
  });
  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    const result = await erasure.findRequest(principal.merchantId, requestId);
    return result ? result : reply.code(404).send({ error: 'erasure_request_not_found' });
  });
}

