  `SELECT id,billing_snapshot FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
  [merchantId, customerId],
);
for (const invoice of invoices.rows) {
  const snapshot = { ...invoice.billing_snapshot };
  if (typeof snapshot.customer === 'object' && snapshot.customer !== null) {
    snapshot.customer = redactSnapshot(snapshot.customer as Record<string, unknown>, customerId);
  }
  await client.query(`UPDATE payments.invoices SET billing_snapshot=$2 WHERE id=$1`, [invoice.id, snapshot]);
}

