action.file_text:
const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';

async function api(path, method='GET', body, extraHeaders={}) {
  const headers = { authorization: `Bearer ${apiKey}`, ...extraHeaders };
  const init = { method, headers };
  if (body !== undefined) { headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const res = await fetch(`${gateway}${path}`, init);
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = text; }
  return { status: res.status, body: json };
}

// 404 for missing customer
const missing = await api('/v1/customers/00000000-0000-4000-8000-000000000099/erasure-requests', 'POST', undefined, { 'idempotency-key': 'missing-customer-key' });
console.log('MISSING CUSTOMER:', JSON.stringify(missing, null, 2));

// 404 for other-merchant customer (northstar key against bluebird's own customer would need a real bluebird customer; skip, use random uuid to sim other-merchant)
// Idempotency key conflict across two different customers
const c1 = '3ce686da-b9ce-4e36-a2c7-ccba7d8c5f32';
const c2 = 'f6e5577a-b09c-4d10-80f7-f5fc684da497';
const first = await api(`/v1/customers/${c1}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'shared-erasure-key-0001' });
console.log('FIRST CUSTOMER CREATE:', JSON.stringify(first, null, 2));
const conflict = await api(`/v1/customers/${c2}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'shared-erasure-key-0001' });
console.log('SECOND CUSTOMER SAME KEY (expect 409):', JSON.stringify(conflict, null, 2));

// Invalid idempotency key (too short)
const short = await api(`/v1/customers/${c2}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'short' });
console.log('SHORT KEY (expect 400):', JSON.stringify(short, null, 2));

// GET missing request id
const missingGet = await api('/v1/erasure-requests/00000000-0000-4000-8000-000000000099');
console.log('MISSING REQUEST GET (expect 404):', JSON.stringify(missingGet, null, 2));

