const gateway='http://localhost:3000';
const bluebirdKey='pf_local_dev_bluebird_924bd90d2201';
const otherCustomer='f464dfd2-efea-496c-b115-3a4a029898d4'; // northstar customer
const otherRequest='9e3cae42-922f-4048-b037-7735049394ee'; // northstar erasure request
(async () => {
  const r1 = await fetch(gateway+'/v1/customers/'+otherCustomer+'/erasure-requests', { method:'POST', headers: { authorization: 'Bearer '+bluebirdKey, 'idempotency-key':'cross-tenant-key-0001' } });
  console.log('CROSS-TENANT CREATE:', r1.status, JSON.stringify(await r1.json()));
  const r2 = await fetch(gateway+'/v1/erasure-requests/'+otherRequest, { headers: { authorization: 'Bearer '+bluebirdKey } });
  console.log('CROSS-TENANT GET:', r2.status, JSON.stringify(await r2.json()));
})();
"

